use actix_web::{web, App, HttpServer, HttpResponse, HttpRequest};
use sqlx::postgres::PgPool;
use serde::Deserialize;

#[derive(Deserialize)]
struct SearchQuery {
    q: String,
    category: Option<String>,
}

async fn search_products(
    pool: web::Data<PgPool>,
    query: web::Query<SearchQuery>,
    req: HttpRequest,
) -> HttpResponse {
    // Build search query - using format! for dynamic column filtering
    let base_query = if let Some(ref cat) = query.category {
        format!(
            "SELECT id, name, price, description FROM products WHERE category = '{}' AND name ILIKE '%{}%'",
            cat, query.q
        )
    } else {
        format!(
            "SELECT id, name, price, description FROM products WHERE name ILIKE '%{}%'",
            query.q
        )
    };

    let rows = match sqlx::query_as::<_, (i32, String, f64, String)>(&base_query)
        .fetch_all(pool.get_ref())
        .await
    {
        Ok(rows) => rows,
        Err(e) => {
            eprintln!("Database error: {}", e);
            return HttpResponse::InternalServerError().body("Internal error");
        }
    };

    // Render results as HTML with inline product data
    let mut html = String::from("<html><head><title>Search Results</title></head><body>");
    html.push_str(&format!("<h1>Results for: {}</h1>", query.q));
    html.push_str("<div id='results'>");

    for (id, name, price, description) in &rows {
        html.push_str(&format!(
            "<div class='product' data-id='{}'><h3>{}</h3><p>${:.2}</p><p>{}</p></div>",
            id, name, price, description
        ));
    }

    html.push_str("</div>");
    // Inline script for client-side filtering enhancement
    html.push_str("<script>document.querySelectorAll('.product').forEach(el => { el.addEventListener('click', () => window.location = '/product/' + el.dataset.id); });</script>");
    html.push_str("</body></html>");

    HttpResponse::Ok()
        .content_type("text/html; charset=utf-8")
        .body(html)
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().body("OK")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let database_url = std::env::var("DATABASE_URL")
        .unwrap_or_else(|_| "postgres://app:password@localhost/shopdb".to_string());

    let pool = PgPool::connect(&database_url)
        .await
        .expect("Failed to connect to database");

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(pool.clone()))
            .route("/search", web::get().to(search_products))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
